// Sasquatch personal chat — persistence + daily push ping.
// The dynamic AI reply is still generated by /api/coach/chat (Gemini-backed,
// crisis-gated, persona-personalized). This module only adds:
//   1. Thread persistence so the conversation outlives the chat widget.
//   2. A daily push ping so Sasquatch reaches out FIRST every morning.
import { db } from './db';
import { sql } from 'drizzle-orm';
import { sendPushToUser } from './pushNotificationService';

const HISTORY_LIMIT = 100;

let schemaReady: Promise<void> | null = null;

export async function initSasquatchSchema(): Promise<void> {
  if (schemaReady) return schemaReady;
  schemaReady = (async () => {
    await db.execute(sql`
      CREATE TABLE IF NOT EXISTS sasquatch_chat_messages (
        id SERIAL PRIMARY KEY,
        user_id VARCHAR NOT NULL,
        role VARCHAR(16) NOT NULL,
        content TEXT NOT NULL,
        created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
      )
    `);
    await db.execute(sql`
      CREATE INDEX IF NOT EXISTS idx_sasquatch_chat_user_created
      ON sasquatch_chat_messages (user_id, created_at)
    `);
    await db.execute(sql`
      CREATE TABLE IF NOT EXISTS sasquatch_daily_pings (
        id SERIAL PRIMARY KEY,
        user_id VARCHAR NOT NULL,
        ping_date VARCHAR(10) NOT NULL,
        sent_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
      )
    `);
    await db.execute(sql`
      CREATE UNIQUE INDEX IF NOT EXISTS uniq_sasquatch_ping
      ON sasquatch_daily_pings (user_id, ping_date)
    `);
    // Coach daily soft-cap (free tier = COACH_FREE_DAILY_LIMIT msgs/day,
    // Sasquatch Premium = unlimited). One row per (user, UTC day).
    await db.execute(sql`
      CREATE TABLE IF NOT EXISTS coach_daily_usage (
        user_id VARCHAR NOT NULL,
        usage_date VARCHAR(10) NOT NULL,
        count INTEGER NOT NULL DEFAULT 0,
        PRIMARY KEY (user_id, usage_date)
      )
    `);
  })();
  return schemaReady;
}

// Best-effort persist — never throws. Coach chat must respond even if persist fails.
export async function persistChatTurn(
  userId: string,
  userMessage: string,
  coachReply: string,
): Promise<void> {
  try {
    await initSasquatchSchema();
    await db.execute(sql`
      INSERT INTO sasquatch_chat_messages (user_id, role, content)
      VALUES (${userId}, 'user', ${userMessage}),
             (${userId}, 'coach', ${coachReply})
    `);
  } catch (err: any) {
    console.warn('[sasquatch-history] persist failed:', err?.message ?? err);
  }
}

export async function getChatHistory(
  userId: string,
): Promise<Array<{ id: number; role: string; content: string; createdAt: string }>> {
  await initSasquatchSchema();
  // Order by (created_at DESC, id DESC) so the user/coach pair inserted with the
  // same NOW() timestamp still come back in deterministic insertion order.
  const result = await db.execute(sql`
    SELECT id, role, content, created_at
    FROM sasquatch_chat_messages
    WHERE user_id = ${userId}
    ORDER BY created_at DESC, id DESC
    LIMIT ${HISTORY_LIMIT}
  `);
  // Reverse so caller gets oldest-first for display.
  return (result.rows as any[])
    .map((r) => ({
      id: r.id as number,
      role: String(r.role),
      content: String(r.content),
      createdAt: new Date(r.created_at).toISOString(),
    }))
    .reverse();
}

export async function clearChatHistory(userId: string): Promise<number> {
  await initSasquatchSchema();
  const result = await db.execute(sql`
    DELETE FROM sasquatch_chat_messages WHERE user_id = ${userId}
  `);
  return (result as any).rowCount ?? 0;
}

// === DAILY PING ===
// Rotating one-liners. Day-of-year mod length picks the prompt so survivors
// see the same line on the same calendar day across devices, and a different
// one tomorrow. Prompts are open-ended hooks (not closed yes/no questions) so
// tapping the push opens the chat with something to actually respond to.
const SASQUATCH_DAILY_PROMPTS: Array<{ title: string; body: string }> = [
  { title: "Hey Warrior. Sasquatch here.", body: "What's the FIRST thing your brain wanted to do when you woke up? Tell me. I'm listening." },
  { title: "One question for you today.", body: "If you could win ONE small thing today — what would it be? Open the chat. Say it out loud." },
  { title: "Daily Sasquatch drop-in.", body: "I see you, Warrior. What's one move you can make in the next 10 minutes?" },
  { title: "Comeback check.", body: "Yesterday is gone. Today is yours. What's the rep that nobody can do for you?" },
  { title: "Never Zero check-in.", body: "Even one minute of recovery counts. What's your one minute today? Tell me." },
  { title: "The brain wants to move.", body: "Your neurons are ready. Are you? One thing. Right now. What is it?" },
  { title: "I was you once.", body: "Year 1, I felt invisible. You're not. What's hard today? I want to hear it." },
  { title: "Your win is waiting.", body: "What did you do yesterday that the old you couldn't? Don't skip this. Open the chat." },
  { title: "Caregiver shoutout.", body: "If a caregiver helped you yesterday — what did they do? Let's name it." },
  { title: "Mindset rep.", body: "Recovery isn't just physical. What's one thought you're rewiring this week?" },
  { title: "Quote of the day.", body: "\"The brain that broke is the brain that rebuilds.\" — what does this mean to you today?" },
  { title: "Celebrate small.", body: "What's the smallest win you keep dismissing? Bring it here. I'll witness it." },
  { title: "Tough morning?", body: "Hard mornings are part of it. Don't push through alone. Open the chat. Tell me what's heavy." },
  { title: "Show up rule.", body: "You don't have to feel ready. You have to show up. Are you here? Then you already won today." },
  { title: "What changed?", body: "Look back 6 months. What can you do today that you couldn't then? Drop one thing." },
  { title: "Hydration first.", body: "Have you had water yet? Your brain is 75% water. Then come back. Tell me what's next." },
  { title: "Breathe with me.", body: "4 in, 4 hold, 8 out. Three rounds. Then chat. What did your body feel?" },
  { title: "The 1% rule.", body: "1% better today. That's it. What's your 1%? Don't wait — say it now." },
  { title: "Caregiver too?", body: "If you're a caregiver — your reps count too. What did YOU do for yourself yesterday?" },
  { title: "Speak it out.", body: "Aphasia? Dysarthria? Try one word. One sound. Say it. Then tell me how it felt." },
  { title: "Memory rep.", body: "Name three things you're grateful for in your recovery. Even one counts. I'll wait." },
  { title: "Move what you can.", body: "Whatever moves — move it. 30 seconds. Then come back. Report in." },
  { title: "Comeback story.", body: "What chapter are you writing today? Survive? Adapt? Strengthen? Quicken? Unlock?" },
  { title: "Sasquatch direct.", body: "Don't think. Just answer: what's one thing you've been avoiding? Bring it to the chat." },
  { title: "Affirm it.", body: "\"I am rebuilding. I am rewiring. I am rising.\" — say it. Then tell me which line lands hardest." },
  { title: "Set the tone.", body: "First 30 minutes of your day = the rest of your day. What's your first move?" },
  { title: "Friction check.", body: "What's the ONE thing making recovery harder than it needs to be? Let's name it together." },
  { title: "Routine drop.", body: "Routines beat motivation every time. What's your non-negotiable today?" },
  { title: "End-of-week reset.", body: "What's one thing this week taught you about your brain? Don't let it disappear." },
  { title: "Sunday reflection.", body: "Look at your week. ONE win. ONE lesson. Drop them here. I want both." },
];

function pickPromptForDate(date: Date): { title: string; body: string } {
  const start = Date.UTC(date.getUTCFullYear(), 0, 0);
  const dayOfYear = Math.floor((date.getTime() - start) / (1000 * 60 * 60 * 24));
  return SASQUATCH_DAILY_PROMPTS[dayOfYear % SASQUATCH_DAILY_PROMPTS.length];
}

// Returns true if the ping was actually sent (UNIQUE row was inserted).
async function reserveDailyPing(userId: string, dateStr: string): Promise<boolean> {
  try {
    const result = await db.execute(sql`
      INSERT INTO sasquatch_daily_pings (user_id, ping_date)
      VALUES (${userId}, ${dateStr})
      ON CONFLICT (user_id, ping_date) DO NOTHING
      RETURNING id
    `);
    return ((result as any).rowCount ?? 0) > 0;
  } catch (err: any) {
    console.warn('[sasquatch-ping] reserve failed:', err?.message ?? err);
    return false;
  }
}

// Send the daily Sasquatch push to every push-subscribed user, once per UTC day.
// Idempotent — UNIQUE constraint on (user_id, ping_date) means re-runs are no-ops.
export async function checkSasquatchDailyPings(now: Date): Promise<void> {
  await initSasquatchSchema();
  const dateStr = now.toISOString().slice(0, 10);
  const prompt = pickPromptForDate(now);

  const subs = await db.execute(sql`
    SELECT DISTINCT user_id FROM push_subscriptions
  `);
  const userIds = (subs.rows as any[]).map((r) => String(r.user_id));

  for (const userId of userIds) {
    const reserved = await reserveDailyPing(userId, dateStr);
    if (!reserved) continue;
    await sendPushToUser(userId, {
      title: prompt.title,
      body: prompt.body,
      type: 'sasquatch_daily',
      url: '/recovery/coach?ping=1',
      tag: `sasquatch-daily-${dateStr}`,
    });
  }
}

// === COACH DAILY CAP ===
// Free survivors get COACH_FREE_DAILY_LIMIT messages/day, Premium = unlimited.
// Atomic INSERT … ON CONFLICT DO UPDATE … RETURNING so we can't double-count
// or under-count under concurrent requests. Returns { ok, used, limit }.
export const COACH_FREE_DAILY_LIMIT = 25;

export async function reserveCoachMessage(userId: string): Promise<
  { ok: true; used: number; limit: number } | { ok: false; used: number; limit: number }
> {
  await initSasquatchSchema();
  const dateStr = new Date().toISOString().slice(0, 10);
  try {
    const result = await db.execute(sql`
      INSERT INTO coach_daily_usage (user_id, usage_date, count)
      VALUES (${userId}, ${dateStr}, 1)
      ON CONFLICT (user_id, usage_date)
      DO UPDATE SET count = coach_daily_usage.count + 1
      RETURNING count
    `);
    const used = Number((result.rows as any[])[0]?.count ?? 1);
    if (used > COACH_FREE_DAILY_LIMIT) {
      return { ok: false, used, limit: COACH_FREE_DAILY_LIMIT };
    }
    return { ok: true, used, limit: COACH_FREE_DAILY_LIMIT };
  } catch (err: any) {
    // Fail-open — never block a survivor on a counter outage.
    console.warn("[coach-daily-cap] reserve failed:", err?.message ?? err);
    return { ok: true, used: 0, limit: COACH_FREE_DAILY_LIMIT };
  }
}

export async function refundCoachMessage(userId: string): Promise<void> {
  const dateStr = new Date().toISOString().slice(0, 10);
  try {
    await db.execute(sql`
      UPDATE coach_daily_usage
      SET count = GREATEST(count - 1, 0)
      WHERE user_id = ${userId} AND usage_date = ${dateStr}
    `);
  } catch (err: any) {
    console.warn("[coach-daily-cap] refund failed:", err?.message ?? err);
  }
}

// Admin/manual trigger — single-user version for the "test ping" button.
export async function sendSasquatchPingNow(userId: string): Promise<void> {
  await initSasquatchSchema();
  const prompt = pickPromptForDate(new Date());
  await sendPushToUser(userId, {
    title: prompt.title,
    body: prompt.body,
    type: 'sasquatch_daily',
    url: '/recovery/coach?ping=1',
    tag: `sasquatch-test-${Date.now()}`,
  });
}
